SELECT t0.CITY AS "City" FROM ref_data.branch AS t0 LEFT OUTER JOIN (SELECT DISTINCT t2.BRANCH_ID AS "BRANCH_ID" FROM ref_data.account_master AS t2 WHERE t2.in_z <= '2021-06-01 12:00:00' AND (t2.out_z > '2021-06-01 12:00:00' OR t2.out_z IS NULL)) AS t1 ON (t0.ID = t1.BRANCH_ID) WHERE t1.BRANCH_ID IS NOT NULL
